  if (label) label.textContent = name;

  const avatar = document.getElementById('user-avatar');
  if (avatar) avatar.src = USERS[name] || '';

  loadDashboard();
}

function logout() {
  try { sessionStorage.removeItem('n8n_user'); } catch(e) {}
  location.reload();
}

(function checkSession() {
  let u = null;
  try { u = sessionStorage.getItem('n8n_user'); } catch(e) {}
  if (u) { selectUser(u); }
})();

// ── UTILIDADES ──
function toast(msg, ok) {
  const el = document.getElementById('toast');
  if (!el) return;
  const isOk = ok !== false;
  el.innerHTML = (isOk ? '<i class="ph-fill ph-check-circle" style="color:var(--green)"></i>' : '<i class="ph-fill ph-warning-circle" style="color:var(--red)"></i>') + ' ' + msg;
  el.classList.add('show');
  setTimeout(function() { el.classList.remove('show'); }, 3000);
}

function esc(s) {
  return (s || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/'/g, "\\'");
}

function timeAgo(d) {
  if (!d) return '';
  const now = Date.now();
  const t = new Date(d).getTime();
  const s = Math.floor((now - t) / 1000);
  if (s < 60) return 'hace ' + s + 's';
  if (s < 3600) return 'hace ' + Math.floor(s / 60) + 'm';
  if (s < 86400) return 'hace ' + Math.floor(s / 3600) + 'h';
  if (s < 604800) return 'hace ' + Math.floor(s / 86400) + 'd';
  return new Date(d).toLocaleDateString('es');
}

// ── BÚSQUEDA Y ATAJOS ──
function filterWorkflows(q) {
  q = q.toLowerCase();
  document.querySelectorAll('.wf-row').forEach(function(r) {
    const n = r.getAttribute('data-wf-name') || '';
    r.style.display = n.toLowerCase().includes(q) ? '' : 'none';
  });
}

document.addEventListener('keydown', function(e) {
  if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
    e.preventDefault();
    document.getElementById('search-input').focus();
  }
  if (e.key === 'Escape') closeModal();
});

// ── API Y DATOS ──
async function api(params) {
  params.user = currentUser;
  const url = WEBHOOK + '?' + new URLSearchParams(params).toString();
  const r = await fetch(url);
  if (!r.ok) throw new Error('HTTP ' + r.status);
  return r.json();
}

async function loadDashboard() {
  const c = document.getElementById('dashboard-content');
  if (!c) return;
  c.innerHTML = '<div class="loader"><i class="ph ph-spinner-gap spin"></i> Obteniendo datos...</div>';

  try {
    const data = await api({ action: 'fetchAllWorkflows' });
    allData = data;

    const synced = data.synced || [];
    const n8nOnly = data.n8nOnly || [];
    const ghOnly = data.githubOnly || [];

    document.getElementById('cnt-synced').textContent = synced.length;
    document.getElementById('cnt-n8n').textContent = n8nOnly.length;
    document.getElementById('cnt-gh').textContent = ghOnly.length;
    document.getElementById('cnt-total').textContent = synced.length + n8nOnly.length + ghOnly.length;

    let h = '';
    // Agregamos tu genial botón de Sync All
    const syncAllBtn = '<button class="btn primary" onclick="syncAllPending()"><i class="ph ph-cloud-arrow-up"></i> Sync All</button>';

    if (n8nOnly.length) h += renderSection('Pendientes de subir', n8nOnly, 'n8nOnly', 'var(--yellow)', n8nOnly.length, syncAllBtn);
    if (ghOnly.length) h += renderSection('Solo en GitHub', ghOnly, 'ghOnly', 'var(--accent)', ghOnly.length, '');
    if (synced.length) h += renderSection('Sincronizados', synced, 'synced', 'var(--green)', synced.length, '');

    if (!h) h = '<div class="empty">No hay workflows en este repositorio.</div>';
    c.innerHTML = h;
  } catch(e) {
    c.innerHTML = '<div class="empty"><i class="ph ph-warning-circle"></i> Error de conexión: ' + e.message + '</div>';
  }
}

function renderSection(title, items, type, color, count, extra) {
  const rows = items.map(function(wf, i) { return renderRow(wf, type, i); }).join('');
  return '<div class="section-header"><div class="section-title"><span class="dot" style="background:' + color + '"></span> ' + title + ' <span class="badge" style="background:' + color + '15;color:' + color + '">' + count + '</span></div><div class="section-actions">' + extra + '</div></div><div class="wf-list" data-section="' + type + '">' + rows + '</div>';
}

function renderRow(wf, type, i) {
  const active = wf.active;
  const dotClass = active ? 'active' : 'inactive';
  const id = wf.wf_id || '';
  const name = wf.name || id;
  const path = Array.isArray(wf.path) ? (wf.path[0] || '') : (wf.path || '');

  const ghLink = wf.wf_url ? '<a href="' + wf.wf_url + '" target="_blank"><i class="ph ph-arrow-square-out"></i> GitHub</a>' : '';
  const updated = wf.updatedAt ? timeAgo(wf.updatedAt) : '';

  let meta = '<span>ID: ' + id + '</span>';
  if (updated) meta += '<span><i class="ph ph-clock"></i> ' + updated + '</span>';
  if (ghLink) meta += ghLink;

  let actions = '';

  if ((type === 'synced' || type === 'n8nOnly') && id) {
    actions += '<a href="' + N8N_INSTANCE + '/workflow/' + id + '" target="_blank" class="btn"><i class="ph ph-arrow-square-out"></i> Abrir</a>';
  }
  if (id) {
    actions += '<label class="toggle-switch"><input type="checkbox" onchange="toggleWf(\\'' + id + '\\', this.checked)" ' + (active ? 'checked' : '') + '><span class="slider"></span></label>';
  }
  if ((type === 'n8nOnly' || type === 'synced') && id) {
    const label = type === 'synced' ? 'Actualizar' : 'Sync';
    actions += '<button class="btn primary" onclick="syncWf(\\'' + id + '\\', \\'' + esc(path) + '\\', \\'' + esc(name) + '\\')"><i class="ph ph-cloud-arrow-up"></i> ' + label + '</button>';
  }
  if (wf.path) {
    actions += '<button class="btn" onclick="viewCommits(\\'' + esc(path) + '\\', \\'' + id + '\\', \\'' + esc(name) + '\\')"><i class="ph ph-git-commit"></i></button>';
  }
  if (type === 'ghOnly') {
    actions += '<button class="btn primary" onclick="importWf(\\'' + esc(path) + '\\', \\'' + id + '\\', \\'' + esc(name) + '\\')"><i class="ph ph-download-simple"></i> Importar</button>';
  }

  return '<div class="wf-row fade-up" style="animation-delay:' + (0.05 * i) + 's" data-wf-name="' + esc(name) + '"><div class="wf-status-dot ' + dotClass + '"></div><div class="wf-info"><div class="wf-name">' + name + '</div><div class="wf-meta">' + meta + '</div></div><div class="wf-actions">' + actions + '</div></div>';
}

// ── ACCIONES ──
async function toggleWf(id, active) {
  try {
    await api({ action: 'toggleStatus', workflowId: id, active: String(active) });
    toast(active ? 'Workflow activado' : 'Workflow desactivado');
  } catch(e) {
    toast('Error al cambiar estado', false);
  }
}

async function syncWf(id, path, name) {
  const msg = prompt('Mensaje del commit (opcional):', 'Update: ' + name);
  if (msg === null) return;
  try {
    toast('Sincronizando...');
    await api({ action: 'syncWorkflow', workflowId: id, path: JSON.stringify([path]), commitMessage: msg || '' });
    toast('Guardado correctamente');
    loadDashboard();
  } catch(e) {
    toast('Error al sincronizar', false);
  }
}

async function syncAllPending() {
  if (!allData || !allData.n8nOnly || !allData.n8nOnly.length) return;
  if (!confirm('¿Sincronizar ' + allData.n8nOnly.length + ' workflows pendientes?')) return;

  let ok = 0, fail = 0;
  for (let i = 0; i < allData.n8nOnly.length; i++) {
    const wf = allData.n8nOnly[i];
    const pathString = Array.isArray(wf.path) ? wf.path[0] : wf.path;
    try {
      await api({ action: 'syncWorkflow', workflowId: wf.wf_id, path: JSON.stringify([pathString]), commitMessage: '[Batch Sync] ' + wf.name });
      ok++;
    } catch(e) {
      fail++;
    }
  }
  toast('Sync completado: ' + ok + ' OK' + (fail ? ' / ' + fail + ' errores' : ''));
  loadDashboard();
}

async function viewCommits(path, id, name) {
