main{max-width:1100px;margin:0 auto;padding:28px 20px 60px}
.search-wrap{position:relative;margin-bottom:24px}
.search-wrap i{position:absolute;left:14px;top:50%;transform:translateY(-50%);color:var(--text3);font-size:1rem}
.search-wrap input{width:100%;background:var(--surface-solid);border:1px solid var(--border);border-radius:var(--radius);padding:10px 14px 10px 40px;color:var(--text);font-size:.85rem;font-family:inherit;outline:none;transition:border-color .2s}
.search-wrap input:focus{border-color:var(--accent)}
.search-wrap input::placeholder{color:var(--text3)}
.search-wrap kbd{position:absolute;right:12px;top:50%;transform:translateY(-50%);background:var(--surface2);border:1px solid var(--border);border-radius:4px;padding:2px 6px;font-size:.65rem;color:var(--text3);font-family:inherit}
.stats-bar{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:28px}
@media(max-width:768px){.stats-bar{grid-template-columns:repeat(2,1fr)}}
.stat-card{background:var(--surface-solid);border:1px solid var(--border);border-radius:var(--radius);padding:18px 20px;display:flex;flex-direction:column;gap:6px;transition:border-color .2s}
.stat-card:hover{border-color:var(--border-hover)}
.stat-label{font-size:.7rem;color:var(--text2);text-transform:uppercase;letter-spacing:.05em;font-weight:500;display:flex;align-items:center;gap:6px}
.stat-label i{font-size:.85rem}
.stat-value{font-size:1.8rem;font-weight:700;font-variant-numeric:tabular-nums;letter-spacing:-.02em}
.section-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;margin-top:8px}
.section-title{font-size:.8rem;font-weight:600;text-transform:uppercase;letter-spacing:.04em;display:flex;align-items:center;gap:8px}
.section-title .dot{width:7px;height:7px;border-radius:50%;display:inline-block}
.section-actions{display:flex;gap:8px}
.badge{display:inline-flex;align-items:center;justify-content:center;min-width:22px;height:22px;border-radius:6px;padding:0 7px;font-size:.7rem;font-weight:600}
.wf-list{display:flex;flex-direction:column;gap:6px;margin-bottom:32px}
.wf-row{background:var(--surface-solid);border:1px solid var(--border);border-radius:var(--radius);padding:14px 18px;display:flex;align-items:center;gap:14px;transition:all .2s}
.wf-row:hover{border-color:var(--border-hover);background:var(--surface2)}
.wf-status-dot{width:8px;height:8px;border-radius:50%;flex-shrink:0}
.wf-status-dot.active{background:var(--green);box-shadow:0 0 8px rgba(34,197,94,0.4)}
.wf-status-dot.inactive{background:var(--text3)}
.wf-info{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px}
.wf-name{font-weight:500;font-size:.85rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.wf-meta{font-size:.75rem;color:var(--text2);display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.wf-meta a{color:var(--text3);text-decoration:none;display:inline-flex;align-items:center;gap:3px;transition:color .2s}
.wf-meta a:hover{color:var(--text)}
.wf-actions{display:flex;gap:6px;flex-shrink:0;align-items:center}
.btn{padding:6px 12px;border-radius:7px;border:1px solid var(--border);background:var(--surface-solid);color:var(--text);cursor:pointer;font-size:.78rem;font-weight:500;transition:all .15s;white-space:nowrap;display:inline-flex;align-items:center;gap:5px;text-decoration:none;font-family:inherit}
.btn i{font-size:.95rem;color:var(--text2);transition:color .15s;pointer-events:none;}
.btn:hover{background:var(--surface2);border-color:var(--border-hover)}
.btn:hover i{color:var(--text)}
.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}
.btn.primary i{color:rgba(255,255,255,0.8)}
.btn.primary:hover{background:var(--accent2);border-color:var(--accent2)}
.toggle-switch{position:relative;width:34px;height:18px;display:flex;align-items:center;flex-shrink:0}
.toggle-switch input{opacity:0;width:0;height:0;position:absolute}
.slider{position:absolute;inset:0;background:var(--surface3);border-radius:18px;cursor:pointer;transition:.2s}
.slider:before{content:'';position:absolute;width:12px;height:12px;left:3px;bottom:3px;background:var(--text);border-radius:50%;transition:.2s}
input:checked+.slider{background:var(--green)}
input:checked+.slider:before{transform:translateX(16px);background:#fff}
.modal-bg{position:fixed;inset:0;background:rgba(0,0,0,0.6);backdrop-filter:blur(8px);display:none;align-items:center;justify-content:center;z-index:500}
.modal-bg.open{display:flex}
.modal{background:var(--surface-solid);border:1px solid var(--border);border-radius:14px;padding:28px;max-width:580px;width:92%;max-height:80vh;overflow-y:auto;box-shadow:0 24px 48px rgba(0,0,0,0.3)}
.modal h2{font-size:1rem;font-weight:600;display:flex;align-items:center;gap:8px}
.commit-item{padding:14px 0;border-bottom:1px solid var(--border)}
.commit-item:last-child{border-bottom:none}
.commit-msg{font-size:.85rem;font-weight:500;margin-bottom:6px}
.commit-meta{font-size:.75rem;color:var(--text2);display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.commit-meta i{font-size:.85rem}
.loader{display:flex;align-items:center;justify-content:center;padding:48px;color:var(--text2);gap:8px;font-size:.85rem}
@keyframes spin{to{transform:rotate(360deg)}}
.spin{animation:spin .8s linear infinite;display:inline-block}
.empty{text-align:center;padding:48px 20px;color:var(--text3);font-size:.85rem;border:1px dashed var(--border);border-radius:var(--radius)}
#toast{position:fixed;bottom:24px;right:24px;background:var(--surface-solid);border:1px solid var(--border);border-radius:var(--radius);padding:10px 16px;font-size:.82rem;font-weight:500;box-shadow:0 8px 24px rgba(0,0,0,0.3);z-index:9999;opacity:0;transform:translateY(12px);transition:all .3s cubic-bezier(.16,1,.3,1);pointer-events:none;display:flex;align-items:center;gap:8px}
#toast.show{opacity:1;transform:translateY(0)}
@keyframes fadeUp{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
.fade-up{animation:fadeUp .4s ease both}
footer{max-width:1100px;margin:0 auto;padding:0 20px 32px;text-align:center;font-size:.72rem;color:var(--text3);display:flex;align-items:center;justify-content:center;gap:6px}
footer a{color:var(--text2);text-decoration:none}
footer a:hover{color:var(--text)}
@media(max-width:640px){.wf-row{flex-wrap:wrap}.wf-actions{width:100%;justify-content:flex-end;margin-top:8px}.header-right .repo-badge{display:none}}
</style>
</head>
<body>

<div id="overlay">
  <div class="profile-card">
    <h1>Selecciona tu perfil</h1>
    <p>Elige tu identidad para firmar los commits en GitHub.</p>
    <div class="profile-btns">
      <button class="profile-btn" onclick="selectUser('Nyxu')">
        <img src="https://github.com/FrancisGLM.png" alt="Nyxu" class="avatar-img">Nyxu
      </button>
      <button class="profile-btn" onclick="selectUser('Franco')">
        <img src="https://github.com/Franco-Ingravallo.png" alt="Franco" class="avatar-img">Franco
      </button>
    </div>
  </div>
</div>

<header>
  <div class="logo"><i class="ph-fill ph-git-branch"></i> FrontierAdvice</div>
  <div class="header-right">
    <a class="repo-badge" href="https://github.com/REPO_OWNER_PH/REPO_NAME_PH" target="_blank"><i class="ph ph-github-logo"></i> REPO_OWNER_PH/REPO_NAME_PH</a>
    <div class="user-pill" id="user-pill" style="display:none">
      <img id="user-avatar" src="" alt="avatar"><span id="user-label"></span>
    </div>
    <button class="btn-icon" onclick="loadDashboard()" title="Refrescar"><i class="ph ph-arrows-clockwise"></i></button>
    <button class="btn-icon" onclick="toggleTheme()" title="Cambiar tema" id="theme-btn"><i class="ph ph-moon"></i></button>
    <button class="btn-icon" onclick="logout()" title="Cerrar sesión"><i class="ph ph-sign-out"></i></button>
  </div>
</header>

<main>
  <div class="search-wrap">
    <i class="ph ph-magnifying-glass"></i>
    <input type="text" id="search-input" placeholder="Buscar workflows..." autocomplete="off" oninput="filterWorkflows(this.value)">
    <kbd>Ctrl+K</kbd>
  </div>

  <div class="stats-bar">
    <div class="stat-card fade-up" style="animation-delay:.05s"><div class="stat-label"><i class="ph-fill ph-check-circle" style="color:var(--green)"></i> Sincronizados</div><div class="stat-value" id="cnt-synced" style="color:var(--green)">–</div></div>
    <div class="stat-card fade-up" style="animation-delay:.1s"><div class="stat-label"><i class="ph-fill ph-clock" style="color:var(--yellow)"></i> Pendientes</div><div class="stat-value" id="cnt-n8n" style="color:var(--yellow)">–</div></div>
    <div class="stat-card fade-up" style="animation-delay:.15s"><div class="stat-label"><i class="ph-fill ph-cloud-arrow-down" style="color:var(--accent)"></i> Solo GitHub</div><div class="stat-value" id="cnt-gh" style="color:var(--accent)">–</div></div>
    <div class="stat-card fade-up" style="animation-delay:.2s"><div class="stat-label"><i class="ph-fill ph-stack" style="color:var(--text2)"></i> Total</div><div class="stat-value" id="cnt-total">–</div></div>
  </div>

  <div id="dashboard-content">
    <div class="loader"><i class="ph ph-spinner-gap spin"></i> Cargando datos...</div>
  </div>
</main>

<footer><i class="ph ph-git-branch"></i> GitHub Sync Dashboard · <a href="https://github.com/REPO_OWNER_PH/REPO_NAME_PH" target="_blank">REPO_OWNER_PH/REPO_NAME_PH</a></footer>

<div class="modal-bg" id="modal-commits">
  <div class="modal">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;padding-bottom:14px;border-bottom:1px solid var(--border)">
      <h2 id="modal-title"><i class="ph ph-clock-counter-clockwise"></i> Historial</h2>
      <button class="btn-icon" onclick="closeModal()"><i class="ph ph-x"></i></button>
    </div>
    <div id="modal-body"></div>
  </div>
</div>

<div id="toast"></div>

<script>
// Manejador global de errores para que no "muera" en silencio
window.onerror = function(msg, url, lineNo) {
  alert('Error en el navegador: ' + msg);
  return false;
};

const WEBHOOK = 'WEBHOOK_URL_PH';
const N8N_INSTANCE = 'INSTANCE_URL_PH';
const USERS = {
  'Nyxu': 'https://github.com/FrancisGLM.png',
  'Franco': 'https://github.com/Franco-Ingravallo.png'
};

let currentUser = '';
let allData = null;

// ── TEMA ──
function applyTheme(t) {
  document.documentElement.setAttribute('data-theme', t);
  const btn = document.getElementById('theme-btn');
  if (btn) btn.innerHTML = t === 'dark' ? '<i class="ph ph-sun"></i>' : '<i class="ph ph-moon"></i>';
}

function toggleTheme() {
  const t = document.documentElement.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
  try { localStorage.setItem('fa_theme', t); } catch(e) { console.warn('Local storage bloqueado'); }
  applyTheme(t);
}

(function initTheme() {
  let t = 'dark';
  try { t = localStorage.getItem('fa_theme') || 'dark'; } catch(e) {}
  applyTheme(t);
})();

// ── SESIÓN ──
function selectUser(name) {
  try { sessionStorage.setItem('n8n_user', name); } catch(e) { console.warn('Session storage bloqueado'); }
  currentUser = name;

  const overlay = document.getElementById('overlay');
  if (overlay) overlay.style.display = 'none';

  const pill = document.getElementById('user-pill');
  if (pill) pill.style.display = 'flex';

  const label = document.getElementById('user-label');
  if (label) label.textContent = name;

  const avatar = document.getElementById('user-avatar');
  if (avatar) avatar.src = USERS[name] || '';

  loadDashboard();
}

function logout() {
  try { sessionStorage.removeItem('n8n_user'); } catch(e) {}
  location.reload();
}

(function checkSession() {
  let u = null;
  try { u = sessionStorage.getItem('n8n_user'); } catch(e) {}
  if (u) { selectUser(u); }
})();

// ── UTILIDADES ──
function toast(msg, ok) {
  const el = document.getElementById('toast');
  if (!el) return;
  const isOk = ok !== false;
  el.innerHTML = (isOk ? '<i class="ph-fill ph-check-circle" style="color:var(--green)"></i>' : '<i class="ph-fill ph-warning-circle" style="color:var(--red)"></i>') + ' ' + msg;
  el.classList.add('show');
  setTimeout(function() { el.classList.remove('show'); }, 3000);
}

function esc(s) {
  return (s || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/'/g, "\\'");
}

function timeAgo(d) {
  if (!d) return '';
  const now = Date.now();
  const t = new Date(d).getTime();
  const s = Math.floor((now - t) / 1000);
  if (s < 60) return 'hace ' + s + 's';
  if (s < 3600) return 'hace ' + Math.floor(s / 60) + 'm';
  if (s < 86400) return 'hace ' + Math.floor(s / 3600) + 'h';
  if (s < 604800) return 'hace ' + Math.floor(s / 86400) + 'd';
  return new Date(d).toLocaleDateString('es');
}

// ── BÚSQUEDA Y ATAJOS ──
function filterWorkflows(q) {
  q = q.toLowerCase();
  document.querySelectorAll('.wf-row').forEach(function(r) {
    const n = r.getAttribute('data-wf-name') || '';
    r.style.display = n.toLowerCase().includes(q) ? '' : 'none';
  });
}

document.addEventListener('keydown', function(e) {
  if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
    e.preventDefault();
    document.getElementById('search-input').focus();
  }
  if (e.key === 'Escape') closeModal();
});

// ── API Y DATOS ──
async function api(params) {
  params.user = currentUser;
  const url = WEBHOOK + '?' + new URLSearchParams(params).toString();
  const r = await fetch(url);
  if (!r.ok) throw new Error('HTTP ' + r.status);
  return r.json();
}

async function loadDashboard() {
  const c = document.getElementById('dashboard-content');
  if (!c) return;
  c.innerHTML = '<div class="loader"><i class="ph ph-spinner-gap spin"></i> Obteniendo datos...</div>';

  try {
    const data = await api({ action: 'fetchAllWorkflows' });
    allData = data;

    const synced = data.synced || [];
    const n8nOnly = data.n8nOnly || [];
    const ghOnly = data.githubOnly || [];

    document.getElementById('cnt-synced').textContent = synced.length;
    document.getElementById('cnt-n8n').textContent = n8nOnly.length;
    document.getElementById('cnt-gh').textContent = ghOnly.length;
    document.getElementById('cnt-total').textContent = synced.length + n8nOnly.length + ghOnly.length;

    let h = '';
    // Agregamos tu genial botón de Sync All
    const syncAllBtn = '<button class="btn primary" onclick="syncAllPending()"><i class="ph ph-cloud-arrow-up"></i> Sync All</button>';

    if (n8nOnly.length) h += renderSection('Pendientes de subir', n8nOnly, 'n8nOnly', 'var(--yellow)', n8nOnly.length, syncAllBtn);
    if (ghOnly.length) h += renderSection('Solo en GitHub', ghOnly, 'ghOnly', 'var(--accent)', ghOnly.length, '');
    if (synced.length) h += renderSection('Sincronizados', synced, 'synced', 'var(--green)', synced.length, '');

    if (!h) h = '<div class="empty">No hay workflows en este repositorio.</div>';
    c.innerHTML = h;
  } catch(e) {
    c.innerHTML = '<div class="empty"><i class="ph ph-warning-circle"></i> Error de conexión: ' + e.message + '</div>';
  }
}

function renderSection(title, items, type, color, count, extra) {
  const rows = items.map(function(wf, i) { return renderRow(wf, type, i); }).join('');
  return '<div class="section-header"><div class="section-title"><span class="dot" style="background:' + color + '"></span> ' + title + ' <span class="badge" style="background:' + color + '15;color:' + color + '">' + count + '</span></div><div class="section-actions">' + extra + '</div></div><div class="wf-list" data-section="' + type + '">' + rows + '</div>';
}

function renderRow(wf, type, i) {
  const active = wf.active;
  const dotClass = active ? 'active' : 'inactive';
  const id = wf.wf_id || '';
  const name = wf.name || id;
  const path = Array.isArray(wf.path) ? (wf.path[0] || '') : (wf.path || '');

  const ghLink = wf.wf_url ? '<a href="' + wf.wf_url + '" target="_blank"><i class="ph ph-arrow-square-out"></i> GitHub</a>' : '';
  const updated = wf.updatedAt ? timeAgo(wf.updatedAt) : '';

  let meta = '<span>ID: ' + id + '</span>';
  if (updated) meta += '<span><i class="ph ph-clock"></i> ' + updated + '</span>';
  if (ghLink) meta += ghLink;

  let actions = '';

  if ((type === 'synced' || type === 'n8nOnly') && id) {
    actions += '<a href="' + N8N_INSTANCE + '/workflow/' + id + '" target="_blank" class="btn"><i class="ph ph-arrow-square-out"></i> Abrir</a>';
  }
  if (id) {
    actions += '<label class="toggle-switch"><input type="checkbox" onchange="toggleWf(\\'' + id + '\\', this.checked)" ' + (active ? 'checked' : '') + '><span class="slider"></span></label>';
  }
  if ((type === 'n8nOnly' || type === 'synced') && id) {
    const label = type === 'synced' ? 'Actualizar' : 'Sync';
    actions += '<button class="btn primary" onclick="syncWf(\\'' + id + '\\', \\'' + esc(path) + '\\', \\'' + esc(name) + '\\')"><i class="ph ph-cloud-arrow-up"></i> ' + label + '</button>';
  }
  if (wf.path) {
    actions += '<button class="btn" onclick="viewCommits(\\'' + esc(path) + '\\', \\'' + id + '\\', \\'' + esc(name) + '\\')"><i class="ph ph-git-commit"></i></button>';
  }
  if (type === 'ghOnly') {
    actions += '<button class="btn primary" onclick="importWf(\\'' + esc(path) + '\\', \\'' + id + '\\', \\'' + esc(name) + '\\')"><i class="ph ph-download-simple"></i> Importar</button>';
  }

  return '<div class="wf-row fade-up" style="animation-delay:' + (0.05 * i) + 's" data-wf-name="' + esc(name) + '"><div class="wf-status-dot ' + dotClass + '"></div><div class="wf-info"><div class="wf-name">' + name + '</div><div class="wf-meta">' + meta + '</div></div><div class="wf-actions">' + actions + '</div></div>';
}

// ── ACCIONES ──
async function toggleWf(id, active) {
  try {
    await api({ action: 'toggleStatus', workflowId: id, active: String(active) });
    toast(active ? 'Workflow activado' : 'Workflow desactivado');
  } catch(e) {
    toast('Error al cambiar estado', false);
  }
}

async function syncWf(id, path, name) {
  const msg = prompt('Mensaje del commit (opcional):', 'Update: ' + name);
  if (msg === null) return;
  try {
    toast('Sincronizando...');
    await api({ action: 'syncWorkflow', workflowId: id, path: JSON.stringify([path]), commitMessage: msg || '' });
    toast('Guardado correctamente');
    loadDashboard();
  } catch(e) {
    toast('Error al sincronizar', false);
  }
}

async function syncAllPending() {
  if (!allData || !allData.n8nOnly || !allData.n8nOnly.length) return;
  if (!confirm('¿Sincronizar ' + allData.n8nOnly.length + ' workflows pendientes?')) return;

  let ok = 0, fail = 0;
  for (let i = 0; i < allData.n8nOnly.length; i++) {
    const wf = allData.n8nOnly[i];
    const pathString = Array.isArray(wf.path) ? wf.path[0] : wf.path;
    try {
      await api({ action: 'syncWorkflow', workflowId: wf.wf_id, path: JSON.stringify([pathString]), commitMessage: '[Batch Sync] ' + wf.name });
      ok++;
    } catch(e) {
      fail++;
    }
  }
  toast('Sync completado: ' + ok + ' OK' + (fail ? ' / ' + fail + ' errores' : ''));
  loadDashboard();
}

async function viewCommits(path, id, name) {
  document.getElementById('modal-title').innerHTML = '<i class="ph ph-clock-counter-clockwise"></i> ' + name;
  document.getElementById('modal-body').innerHTML = '<div class="loader"><i class="ph ph-spinner-gap spin"></i> Cargando...</div>';
  document.getElementById('modal-commits').classList.add('open');

  try {
    const data = await api({ action: 'fetchCommits', workflowId: id, path: JSON.stringify([path]) });
    const commits = Array.isArray(data) ? data : [];

    if (!commits.length) {
      document.getElementById('modal-body').innerHTML = '<div class="empty">Sin commits.</div>';
      return;
    }

    let h = '';
    for (let i = 0; i < commits.length; i++) {
      const c = commits[i];
      const rb = c.sha ? '<button class="btn" style="margin-top:10px" onclick="restoreWf(\\'' + esc(path) + '\\', \\'' + id + '\\', \\'' + c.sha + '\\')"><i class="ph ph-arrow-u-up-left"></i> Restaurar</button>' : '';
      h += '<div class="commit-item"><div class="commit-msg">' + c.message + '</div><div class="commit-meta"><span><i class="ph-fill ph-user-circle"></i> ' + c.committer + '</span><span><i class="ph ph-clock"></i> ' + timeAgo(c.timestamp) + '</span><a href="' + c.url + '" target="_blank" style="color:var(--text3);text-decoration:none"><i class="ph ph-arrow-square-out"></i></a></div>' + rb + '</div>';
    }
    document.getElementById('modal-body').innerHTML = h;
  } catch(e) {
    document.getElementById('modal-body').innerHTML = '<div class="empty">Error: ' + e.message + '</div>';
  }
}

async function restoreWf(path, id, sha) {
  const action = confirm('¿Restaurar esta versión?\\n\\nAceptar = Reemplazar existente\\nCancelar = Crear nuevo') ? 'replace' : 'import_new';
  closeModal();
  try {
    toast('Restaurando...');
    await api({ action: 'importWorkflow', workflowId: id, path: JSON.stringify([path]), sha: sha, importAction: action });
    toast('Workflow restaurado');
    loadDashboard();
  } catch(e) {
    toast('Error al restaurar', false);
  }
}

async function importWf(path, id, name) {
  if (!confirm('¿Importar "' + name + '" a n8n?')) return;
  try {
    toast('Importando...');
    await api({ action: 'importWorkflow', workflowId: id, path: JSON.stringify([path]), sha: '', importAction: 'import_new' });
    toast('Importado exitosamente');
    loadDashboard();
  } catch(e) {
    toast('Error al importar', false);
  }
}

function closeModal() {
  document.getElementById('modal-commits').classList.remove('open');
}

document.getElementById('modal-commits').addEventListener('click', function(e) {
  if (e.target === e.currentTarget) closeModal();
});
</script>
</body>
</html>`;

  // Reemplazo seguro compatible con versiones antiguas de n8n (Usa RegExp globales)
  const finalHtml = html
    .replace(/WEBHOOK_URL_PH/g, WEBHOOK_URL)
    .replace(/INSTANCE_URL_PH/g, instanceUrl)
    .replace(/REPO_OWNER_PH/g, REPO_OWNER)
    .replace(/REPO_NAME_PH/g, REPO_NAME);

  return { data: finalHtml };

} catch (error) {
